// node:fs (initial subset; extended later)

use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, Vm};

pub fn fs_error(vm: &mut Vm, code: &str, _desc: &str, syscall: &str, path: &str, io: Option<&std::io::Error>) -> Value {
    let msg = match io {
        Some(e) => format!("{}: {}, {} '{}'", code, e, syscall, path),
        None => format!("{}: {}, {} '{}'", code, _desc, syscall, path),
    };
    let e = vm.make_error("Error", &msg);
    if let Value::Obj(o) = &e {
        o.set_prop(PropKey::from_str("code"), Value::str(code), WEC);
    }
    e
}

pub fn io_code(e: &std::io::Error) -> &'static str {
    match e.raw_os_error() {
        Some(n) => crate::runtime::util::errno_name(n),
        None => match e.kind() {
            std::io::ErrorKind::NotFound => "ENOENT",
            std::io::ErrorKind::PermissionDenied => "EACCES",
            std::io::ErrorKind::AlreadyExists => "EEXIST",
            _ => "EIO",
        },
    }
}

pub fn create_module(vm: &mut Vm) -> Value {
    let o = vm.new_object();
    let fns: &[(&str, u32, NativeFn)] = &[
        ("readFileSync", 2, read_file_sync),
        ("writeFileSync", 3, write_file_sync),
        ("existsSync", 1, exists_sync),
    ];
    for (n, l, f) in fns {
        vm.def_method(&o, n, *l, *f);
    }
    let p = vm.new_object();
    o.set_str("promises", Value::Obj(p), WEC);
    Value::Obj(o)
}

pub fn path_arg(vm: &mut Vm, v: &Value) -> JsResult<String> {
    match v {
        Value::Str(s) => Ok(s.to_rust_string()),
        Value::Obj(o) if matches!(o.borrow().kind, ObjKind::TypedArray(_)) => Ok(String::from_utf8_lossy(&crate::builtins::typedarray::ta_bytes(o)).to_string()),
        Value::Obj(_) => {
            let h = vm.get_prop_of(v, &PropKey::from_str("href"))?;
            let s = vm.to_string(&h)?.to_rust_string();
            Ok(s.strip_prefix("file://").unwrap_or(&s).to_string())
        }
        other => {
            let d = crate::runtime::util::describe_received(vm, other);
            vm.throw_type(format!("The \"path\" argument must be of type string or an instance of Buffer or URL. Received {}", d))
        }
    }
}

fn read_file_sync(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let p = path_arg(vm, &a.arg(0))?;
    let enc = match a.arg(1) {
        Value::Str(s) => Some(s.to_rust_string()),
        Value::Obj(o) => match vm.get_str(&o, "encoding")? {
            Value::Str(s) => Some(s.to_rust_string()),
            _ => None,
        },
        _ => None,
    };
    match std::fs::read(&p) {
        Ok(b) => match enc {
            Some(e) => {
                let en = crate::runtime::buffer::norm_encoding(&e).unwrap_or("utf8");
                Ok(Value::Str(crate::runtime::buffer::decode_bytes(&b, en)))
            }
            None => crate::runtime::buffer::new_buffer_value(vm, b),
        },
        Err(e) => {
            let err = vm.make_error("Error", &format!("cannot read '{}': {}", p, e));
            if let Value::Obj(o) = &err {
                o.set_prop(PropKey::from_str("code"), Value::str(io_code(&e)), WEC);
            }
            Err(err)
        }
    }
}

fn write_file_sync(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let p = path_arg(vm, &a.arg(0))?;
    let data = crate::runtime::buffer::bytes_of(vm, &a.arg(1))?;
    if let Err(e) = std::fs::write(&p, data) {
        let err = vm.make_error("Error", &format!("cannot write '{}': {}", p, e));
        if let Value::Obj(o) = &err {
            o.set_prop(PropKey::from_str("code"), Value::str(io_code(&e)), WEC);
        }
        return Err(err);
    }
    Ok(Value::Undefined)
}

fn exists_sync(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let p = match path_arg(vm, &a.arg(0)) {
        Ok(p) => p,
        Err(_) => return Ok(Value::Bool(false)),
    };
    Ok(Value::Bool(std::path::Path::new(&p).exists()))
}

