pub fn setup_globals(vm: &mut Vm) {
    let g = vm.global.clone();
    g.set_prop(PropKey::from_str("global"), Value::Obj(g.clone()), WC);
    let cwd = std::env::current_dir().map(|p| p.to_string_lossy().to_string()).unwrap_or_default();
