const fs = require('fs');
const BASE = '/tmp/fsagent/h_' + (process.argv[2] || 'x');
let n = 0;
function fixture() {
  const D = BASE + '/c' + (n++);
  fs.mkdirSync(D, { recursive: true });
  fs.writeFileSync(D + '/f.txt', 'hello');
  fs.mkdirSync(D + '/d');
  fs.writeFileSync(D + '/d/i.txt', 'x');
  fs.mkdirSync(D + '/e');
  fs.writeFileSync(D + '/ro.txt', 'ro');
  fs.chmodSync(D + '/ro.txt', 0o444);
  fs.mkdirSync(D + '/rodir');
  fs.writeFileSync(D + '/rodir/x.txt', 'x');
  fs.chmodSync(D + '/rodir', 0o555);
  fs.mkdirSync(D + '/noperm');
  fs.chmodSync(D + '/noperm', 0o000);
  fs.symlinkSync(D + '/f.txt', D + '/link');
  fs.symlinkSync(D + '/nope', D + '/broken');
  fs.symlinkSync(D + '/loop', D + '/loop');
  return D;
}
function cleanup() {
  try {
    if (fs.existsSync(BASE)) {
      for (const c of fs.readdirSync(BASE)) {
        try { fs.chmodSync(BASE + '/' + c + '/rodir', 0o755); } catch (e) {}
        try { fs.chmodSync(BASE + '/' + c + '/noperm', 0o755); } catch (e) {}
      }
      fs.rmSync(BASE, { recursive: true, force: true });
    }
  } catch (e) { console.log('cleanup failed', e.message); }
}
function fmt(v) {
  if (v === undefined) return 'undefined';
  if (v === null) return 'null';
  if (typeof v === 'string') return JSON.stringify(v);
  if (Buffer.isBuffer(v)) return 'Buffer[' + v.length + '](' + v.toString('hex') + ')';
  if (Array.isArray(v)) return '[' + v.map(fmt).join(',') + ']';
  if (typeof v === 'object') {
    const c = v.constructor ? v.constructor.name : 'null-proto';
    return c + '{' + Object.keys(v).map(k => k + ':' + (typeof v[k] === 'object' && v[k] !== null && !(v[k] instanceof Date) ? '…' : String(v[k]))).join(',') + '}';
  }
  return typeof v + ':' + String(v);
}
function errfmt(e) {
  if (!(e instanceof Error)) return 'THROWN ' + fmt(e);
  const own = Object.getOwnPropertyNames(e).filter(k => k !== 'stack');
  const extra = own.filter(k => k !== 'message').map(k => k + '=' + JSON.stringify(e[k])).join(' ');
  return e.constructor.name + ': ' + e.message + (extra ? ' {' + extra + '}' : '') + ' own=' + own.join('|');
}
function run(cases) {
  cleanup();
  for (const [label, f] of cases) {
    const D = fixture();
    try {
      const r = f(D);
      console.log(label, '=> OK', fmt(r).split(D).join('$D'));
    } catch (e) {
      console.log(label, '=>', errfmt(e).split(D).join('$D'));
    }
  }
  cleanup();
}
module.exports = { run, fmt, errfmt, fs };

