use std::time::Duration;
fn fmt(x: f64) -> String { format!("{}", x) }
fn main() {
    let data = std::fs::read_to_string("/tmp/fsagent/out/stat_ref.txt").unwrap();
    let orig = std::fs::read_to_string("/tmp/fsagent/out/stat_orig.txt").unwrap();
    for (l, o) in data.lines().zip(orig.lines()) {
        let parts: Vec<&str> = l.split_whitespace().collect();
        let oparts: Vec<&str> = o.split_whitespace().collect();
        for i in 0..4 {
            let t = parts[i + 1];
            let (s, n) = t.split_once('.').unwrap();
            let secs: u64 = s.parse().unwrap();
            let nanos: u32 = n.parse().unwrap();
            let d = Duration::new(secs, nanos);
            let c1 = d.as_secs_f64() * 1000.0;
            let c2 = d.as_nanos() as f64 / 1e6;
            let c3 = secs as f64 * 1000.0 + nanos as f64 / 1e6;
            let c4 = (secs as f64 + nanos as f64 / 1e9) * 1000.0;
            let c5 = d.as_micros() as f64 / 1000.0;
            let c6 = d.as_millis() as f64 + (d.subsec_nanos() % 1_000_000) as f64 / 1e6;
            let want = oparts[i + 1];
            let mut m = Vec::new();
            for (name, c) in [("as_secs_f64*1000", c1), ("nanos/1e6", c2), ("s*1000+ns/1e6", c3), ("(s+ns/1e9)*1000", c4), ("micros/1000", c5), ("millis+frac", c6)] {
                if fmt(c) == want { m.push(name); }
            }
            println!("{} field{} want {} -> {:?}", parts[0], i, want, m);
        }
    }
}

