const log = (...a) => console.log(a.map(x => typeof x === 'object' && x !== null ? (Buffer.isBuffer(x) ? 'Buffer(' + x.toString() + ')' : JSON.stringify(x)) : String(x)).join(' '));
(async () => {
  {
    log('=== drain');
