    log('  hwm', w.writableHighWaterMark, w.writableLength);
    w.on('drain', () => log('  drain', w.writableLength));
    log('  w1', w.write('abc'), w.writableLength);
    log('  w2', w.write('defg'), w.writableLength);
    log('  w3', w.write('h'), w.writableLength);
    await new Promise(r => setTimeout(r, 5));
    log('  after', w.writableLength, JSON.stringify(w._writableState, (k, v) => k === 'tail' ? typeof v : v));
  }
  {
    log('=== default hwm');
    const w = new Writable();
    log('  hwm', w.writableHighWaterMark);
    const r = new Readable();
    log('  rhwm', r.readableHighWaterMark);
  }
  {
    log('=== write error');
    const w = new Writable({ write(c, e, cb) { log('  _write', String(c)); cb(new Error('boom ' + c)); } });
    w.on('error', (e) => log('  error event', e.message));
    w.on('finish', () => log('  finish'));
    w.on('close', () => log('  close'));
    w.write('a', (err) => log('  cb a', err && err.message));
    w.write('b');
    w.end('c', (err) => log('  end cb', err && err.message));
    await new Promise(r => setTimeout(r, 5));
    log('  state', JSON.stringify(w._writableState, (k, v) => k === 'tail' ? typeof v : (k === 'errored' && v ? v.message : v)));
  }
  {
    log('=== write after end');
    const w = new Writable({ write(c, e, cb) { cb(); } });
    w.on('error', (e) => log('  error event', e.message));
    w.end();
    log('  ret', w.write('x'));
    log('  ret2', w.write('y', (e) => log('  cb', e.message)));
    await new Promise(r => setTimeout(r, 5));
  }
  {
    log('=== end twice');
    const w = new Writable({ write(c, e, cb) { cb(); } });
    w.on('finish', () => log('  finish'));
    w.end(() => log('  cb1'));
    w.end(() => log('  cb2'));
    await new Promise(r => setTimeout(r, 5));
  }
  {
    log('=== destroy');
    const w = new Writable({ write(c, e, cb) { cb(); } });
    w.on('close', () => log('  close'));
    w.on('error', (e) => log('  error', e.message));
    w.destroy(new Error('d'));
    log('  destroyed sync', w.destroyed, w.writable);
    await new Promise(r => setTimeout(r, 5));
  }
  {
    log('=== write types');
    const w = new Writable({ write(c, e, cb) { log('  _write', typeof c, Buffer.isBuffer(c), String(c), e); cb(); } });
    w.write('str');
    w.write('str2', 'hex');
    w.write(Buffer.from('buf'));
    w.write(new Uint8Array([65]));
    try { w.write(123); } catch (e) { log('  write num err', e.message); }
    try { w.write(null); } catch (e) { log('  write null err', e.message); }
    try { w.write({ a: 1 }); } catch (e) { log('  write obj err', e.message); }
    await new Promise(r => setTimeout(r, 5));
  }
})();

