const { Readable } = require('stream');
const log = (...a) => console.log(a.map(x => typeof x === 'object' && x !== null ? (Buffer.isBuffer(x) ? 'Buffer(' + x.toString() + ')' : JSON.stringify(x)) : String(x)).join(' '));
(async () => {
  {
    log('=== (a) paused then push null');
    const r = new Readable();
    r.pause();
    r.on('end', () => log('  end', r._readableState.flowing));
    r.push(null);
    log('  sync endEmitted', r._readableState.endEmitted, r._readableState.flowing);
    await new Promise(res => setTimeout(res, 5));
    log('  after', JSON.stringify(r._readableState));
    r.resume();
    await new Promise(res => setTimeout(res, 5));
    log('  after resume', JSON.stringify(r._readableState));
  }
  {
    log('=== (b) destroyed then push null');
    const r = new Readable();
    r.on('end', () => log('  end'));
    r.on('close', () => log('  close'));
    r.destroy();
    r.push(null);
    log('  sync', JSON.stringify(r._readableState));
    await new Promise(res => setTimeout(res, 5));
  }
  {
    log('=== (c) flowing during end');
    const r = new Readable();
    r.on('data', () => {});
    r.on('end', () => log('  end flowing=', r._readableState.flowing, r.isPaused()));
    r.push('x');
    r.push(null);
    log('  sync endEmitted', r._readableState.endEmitted, r._readableState.flowing);
    await new Promise(res => setTimeout(res, 5));
    log('  after', r._readableState.flowing);
  }
  {
    log('=== (d) null flowing push data then null, no consumer');
    const r = new Readable();
    r.on('end', () => log('  end'));
    r.push('x');
    r.push(null);
    await new Promise(res => setTimeout(res, 5));
    log('  after', JSON.stringify(r._readableState));
    log('  read', r.read());
    log('  sync after read', JSON.stringify(r._readableState));
    await new Promise(res => setTimeout(res, 5));
  }
  {
    log('=== (e) resume twice / resume returns');
    const r = new Readable();
    log('  resume ret', r.resume() === r, r._readableState.flowing);
    log('  pause ret', r.pause() === r, r.isPaused());
    r.on('data', (c) => log('  data', c));
    log('  after on data while paused', r._readableState.flowing);
    r.push('q');
    log('  buffered', r._readableState.length);
    r.resume();
    log('  sync after resume');
    await new Promise(res => setTimeout(res, 5));
  }
  {
    log('=== (f) once data');
    const r = new Readable();
    r.once('data', (c) => log('  once data', c));
    r.push('1'); r.push('2');
    log('  state', r._readableState.flowing, r._readableState.length);
    await new Promise(res => setTimeout(res, 5));
    log('  state after', r._readableState.flowing, r._readableState.length, r.listenerCount('data'));
  }
  {
    log('=== (g) read(n)');
    const r = new Readable();
    r.push('abc'); r.push('def');
    log('  read2', r.read(2));
    log('  read10', r.read(10));
    log('  read0', r.read(0));
    log('  readall', r.read());
    r.push(null);
    log('  read10 after end', r.read(10));
    log('  read after', r.read());
    try { r.read(-1); } catch (e) { log('  err', e.constructor.name, e.message); }
    try { r.read(1.5); } catch (e) { log('  err', e.constructor.name, e.message); }
  }
  {
    log('=== (h) setEncoding variants');
    for (const e of ['UTF-8', 'utf-16le', 'Hex', 'base64', 'latin1', 'ucs-2']) {
      const r = new Readable();
      r.setEncoding(e);
      r.on('data', (c) => log('  ', e, r._readableState.encoding, JSON.stringify(c)));
      r.push(Buffer.from('hi!'));
    }
    await new Promise(res => setTimeout(res, 5));
  }
  {
    log('=== (i) push string no encoding');
    const r = new Readable();
    r.on('data', (c) => log('  data', typeof c, c));
    r.push('str');
    r.push(new Uint8Array([65, 66]));
    await new Promise(res => setTimeout(res, 5));
  }
  {
    log('=== (j) error in data handler');
    const r = new Readable();
    r.on('data', (c) => { throw new Error('handler threw'); });
    r.push('x');
    log('  after push');
    await new Promise(res => setTimeout(res, 5));
  }
})();

