input.new_string:
fn cp_rec(vm: &mut Vm, src: &str, dest: &str, opts: &Value) -> JsResult<()> {
    let md = match std::fs::symlink_metadata(src) {
        Ok(m) => m,
        Err(e) => return Err(sys_err(vm, &e, "lstat", src)),
    };
    if md.is_dir() {
        if !getp(vm, opts, "recursive")?.truthy() {
            return Err(js_err(vm, "EISDIR", "cp", src, "recursive option not set for a directory"));
        }
        mkdir_impl(vm, dest, true)?;
        // each nested directory costs a JS call frame in the reference (deep recursion ends in
        // "Maximum call stack size exceeded")
        vm.enter()?;
        let r = (|| -> JsResult<()> {
            for name in readdir_names(vm, src)? {
                let s = path_join(src, &name);
                let d = path_join(dest, &name);
                cp_rec(vm, &s, &d, opts)?;
            }
            Ok(())
        })();
        vm.depth -= 1;
        return r;
    }

