const fs = require('fs');
const fsp = require('fs/promises');
const path = require('path');
const util = require('util');

const dir = '/tmp/fsagent/out/t_async';
fs.rmSync(dir, { recursive: true, force: true });

async function main() {
  await fsp.mkdir(dir, { recursive: true });
  await fsp.writeFile(path.join(dir, 'a.txt'), 'alpha');
  await fsp.writeFile(path.join(dir, 'b.txt'), 'beta', 'utf8');
  await fsp.appendFile(path.join(dir, 'a.txt'), '-more');
  const a = await fsp.readFile(path.join(dir, 'a.txt'), 'utf8');
  console.log('a:', a);
  const files = await fsp.readdir(dir);
  console.log('files:', files);
  const stats = await Promise.all(files.map(f => fsp.stat(path.join(dir, f))));
  console.log('sizes:', stats.map(s => s.size));
  try {
    await fsp.readFile(path.join(dir, 'nope.txt'));
  } catch (e) {
    console.log('caught:', e.code, e.message.includes('No such file'));
  }
  try {
    await fsp.access(path.join(dir, 'nope.txt'));
    console.log('accessible');
  } catch (e) {
    console.log('not accessible:', e.code);
  }
  await fsp.rename(path.join(dir, 'b.txt'), path.join(dir, 'c.txt'));
  console.log('after rename:', (await fsp.readdir(dir)).join());
  await fsp.unlink(path.join(dir, 'c.txt'));
  const fh = await fsp.open(path.join(dir, 'a.txt'), 'r');
  const { bytesRead, buffer } = await fh.read(Buffer.alloc(5), 0, 5, 0);
  console.log('fh read:', bytesRead, buffer.toString());
  const st = await fh.stat();
  console.log('fh stat size:', st.size);
  await fh.close();
  await fsp.rm(dir, { recursive: true, force: true });
  console.log('done, exists:', fs.existsSync(dir));
}

function callbackStyle(done) {
  fs.mkdir(dir + '_cb', { recursive: true }, (err) => {
    if (err) throw err;
    fs.writeFile(path.join(dir + '_cb', 'x.txt'), 'xyz', (err) => {
      if (err) throw err;
      fs.readFile(path.join(dir + '_cb', 'x.txt'), 'utf8', (err, data) => {
        console.log('cb read:', err, data);
        fs.stat(path.join(dir + '_cb', 'x.txt'), (err, st) => {
          console.log('cb stat:', st.size, st.isFile());
          fs.readdir(dir + '_cb', (err, list) => {
            console.log('cb readdir:', list);
            fs.rm(dir + '_cb', { recursive: true }, (err) => {
              console.log('cb rm:', err);
              done();
            });
          });
        });
      });
    });
  });
}

const readFileP = util.promisify(fs.readFile);
callbackStyle(() => {
  main().then(async () => {
    fs.writeFileSync('/tmp/fsagent/out/p.txt', 'promisified');
    console.log('promisify:', await readFileP('/tmp/fsagent/out/p.txt', 'utf8'));
    try { await readFileP('/nonexistent'); } catch (e) { console.log('promisify err:', e.code); }
    fs.readFile('/nonexistent', (err, data) => {
      console.log('cb err:', err.code, data);
    });
    fs.exists('/tmp', (e) => console.log('exists cb:', e));
  });
});

