const fs = require('fs');
const P = '/tmp/fsagent/out/rw.txt';
fs.writeFileSync(P, 'hello world');
const fd = fs.openSync(P, 'r+');
const show = (...a) => console.log(a.map(x => Buffer.isBuffer(x) ? 'Buf(' + x.toString('hex') + ')' : (x && typeof x === 'object' ? JSON.stringify(x) : String(x))).join(' '));
fs.read(fd, (err, n, buf) => show('read1', err, n, buf.length, buf.slice(0, n).toString()));
fs.read(fd, Buffer.alloc(4), 0, 4, 0, (err, n, buf) => show('read2', err, n, buf));
fs.read(fd, { buffer: Buffer.alloc(3), position: 6 }, (err, n, buf) => show('read3', err, n, buf));
fs.read(fd, { position: 0, length: 2 }, (err, n, buf) => show('read4', err, n, buf.length, buf.slice(0, 2)));
fs.read(fd, Buffer.alloc(4), 1, 2, 3, function () { show('read5 args', arguments.length, arguments[1], arguments[2]); });
fs.write(fd, 'XY', 0, (err, n, data) => show('write1', err, n, data));
fs.write(fd, Buffer.from('ZZZ'), 0, 2, 5, (err, n, data) => show('write2', err, n, data));
fs.write(fd, 'Q', (err, n, data) => show('write3', err, n, data));
fs.write(fd, 'nocb');
fs.write(fd, Buffer.from('ab'), (err, n) => show('write4', err, n));
fs.readv(fd, [Buffer.alloc(2), Buffer.alloc(3)], 0, (err, n, bufs) => show('readv', err, n, bufs.map(b => b.toString()).join('|')));
fs.writev(fd, [Buffer.from('1'), Buffer.from('2')], (err, n, bufs) => show('writev', err, n, bufs.length));
