(async () => {
  const rs = fs.createReadStream(P, { highWaterMark: 1000 });
  rs.on('close', () => console.log('close event'));
  let n = 0;
  for await (const c of rs) { n++; if (n === 3) break; }
  console.log('broke after', n, rs.destroyed, rs._readableState.destroyed, rs.readable);
  await new Promise(r => setTimeout(r, 10));
  const rs2 = fs.createReadStream(P, { highWaterMark: 50000, encoding: 'latin1' });
  const sizes = [];
  for await (const c of rs2) sizes.push(c.length);
  console.log('sizes', sizes.join(','));
  const rs3 = fs.createReadStream('/nonexistent');
  try { for await (const c of rs3) { } } catch (e) { console.log('iter error', e.message); }
  const order = [];
  const rs4 = fs.createReadStream(P, { highWaterMark: 100000 });
  const p1 = (async () => { for await (const c of rs4) order.push('c' + c.length); order.push('done'); })();
  const p2 = (async () => { for (let i = 0; i < 10; i++) { await null; order.push('t' + i); } })();
  await Promise.all([p1, p2]);
  console.log(order.join(' '));
})();

