fn rm_impl(vm: &mut Vm, path: &str, recursive: bool, force: bool) -> JsResult<Value> {
    let r = match std::fs::symlink_metadata(path) {
        Ok(md) => {
            if md.is_dir() {
                if recursive {
                    std::fs::remove_dir_all(path)
                } else {
                    std::fs::remove_dir(path)
                }
            } else {
                std::fs::remove_file(path)
            }
        }
        Err(e) => Err(e),
    };

