const fs = require('fs');
const which = process.argv[2];
if (which === '1') {
  const ws = fs.createWriteStream('/nonexistent/x');
  ws.write('x', (e) => console.log('cb', e && e.message));
  ws.destroy(new Error('wboom'));
} else if (which === '2') {
  const ws = fs.createWriteStream('/nonexistent/x');
  ws.destroy(new Error('wboom'));
  ws.write('x', (e) => console.log('cb', e && e.message));
} else if (which === '3') {
  const ws = fs.createWriteStream('/nonexistent/x');
  ws.write('x');
  ws.end();
  ws.destroy(new Error('wboom'));
} else if (which === '4') {
  queueMicrotask(() => { throw new Error('qm1'); });
  Promise.resolve().then(() => { throw new Error('then1'); });
  queueMicrotask(() => { throw new Error('qm2'); });
} else if (which === '5') {
  const { Writable } = require('stream');
  const w = new Writable({ write(c, e, cb) { cb(new Error('werr')); } });
  w.write('x');
